const chamados = $('Ler Chamados (F3 Diario)').all().map(function (i) { return i.json; });
const leads = $('Ler Leads (F3 Diario)').all().map(function (i) { return i.json; });
const agora = Date.now();
const janela = 1 * 24 * 3600 * 1000;
const noPeriodo = function (iso) {
  const t = Date.parse(String(iso || ''));
  return !isNaN(t) && agora - t <= janela;
};
const novos = chamados.filter(function (c) { return noPeriodo(c.aberto_em); });
const resolvidos = chamados.filter(function (c) { return c.status === 'resolvido' && noPeriodo(c.resolvido_em); });
const noPrazo = resolvidos.filter(function (c) {
  return Date.parse(String(c.resolvido_em || '')) - Date.parse(String(c.aberto_em || '')) <= Number(c.sla_horas || 0) * 3600000;
});
const emAberto = chamados.filter(function (c) { return !['resolvido', 'cancelado'].includes(String(c.status)); });
const vencidos = emAberto.filter(function (c) { return Number(c.escalado) === 1; });
const leadsNovos = leads.filter(function (l) { return noPeriodo(l.created_at); });
const convertidos = leads.filter(function (l) { return l.status === 'convertido' && noPeriodo(l.convertido_em); });
const semContato = leads.filter(function (l) { return l.status === 'distribuido' && !l.primeiro_contato_em; });
const porOrigem = {};
leadsNovos.forEach(function (l) {
  const o = l.utm_source || 'direto';
  porOrigem[o] = (porOrigem[o] || 0) + 1;
});
const pctSla = resolvidos.length ? Math.round(100 * noPrazo.length / resolvidos.length) : null;
const kpis = {
  novos_chamados: novos.length, chamados_resolvidos: resolvidos.length, pct_sla: pctSla,
  chamados_em_aberto: emAberto.length, chamados_vencidos: vencidos.length,
  leads_novos: leadsNovos.length, leads_convertidos: convertidos.length,
  leads_sem_contato: semContato.length
};
const origens = Object.keys(porOrigem).map(function (o) { return '<li>' + o + ': ' + porOrigem[o] + '</li>'; }).join('');
const whats = 'AureaOps Resumo diario: ' + novos.length + ' chamados novos, ' + resolvidos.length + ' resolvidos (SLA ' + (pctSla === null ? 's/d' : pctSla + '%') + '), ' + leadsNovos.length + ' leads, ' + convertidos.length + ' conversoes.';
return [{ json: {
  criado_em: new Date().toISOString(),
  fluxo: 'F3',
  evento: 'relatorio_diario',
  status: 'sucesso',
  request_id: '',
  http_status: 200,
  detalhe: JSON.stringify(kpis),
  email_para: $env.GESTOR_EMAIL,
  email_assunto: '[AureaOps] Resumo diario - ' + new Date().toISOString().slice(0, 10),
  email_html: '<h2>Resumo diario AureaOps</h2><h3>SAC</h3><ul>' +
    '<li>Novos chamados: ' + kpis.novos_chamados + '</li>' +
    '<li>Resolvidos: ' + kpis.chamados_resolvidos + ' (SLA cumprido: ' + (pctSla === null ? 'sem dados' : pctSla + '%') + ')</li>' +
    '<li>Em aberto: ' + kpis.chamados_em_aberto + ' (vencidos/escalados: ' + kpis.chamados_vencidos + ')</li></ul>' +
    '<h3>Comercial</h3><ul><li>Leads novos: ' + kpis.leads_novos + '</li>' +
    '<li>Convertidos: ' + kpis.leads_convertidos + '</li>' +
    '<li>Sem primeiro contato: ' + kpis.leads_sem_contato + '</li>' +
    '<li>Origens: ' + (origens ? '<ul>' + origens + '</ul>' : 'sem leads no periodo') + '</li></ul>',
  whats_para: $env.GESTOR_WHATSAPP,
  whats_texto: whats,
  whats_body: { messaging_product: 'whatsapp', to: $env.GESTOR_WHATSAPP, type: 'template', template: { name: 'resumo_periodo', language: { code: 'pt_BR' }, components: [{ type: 'body', parameters: [{ type: 'text', text: whats }] }] } }
}}];

